catalog_script_client.script:
function onSubmit() {

    //g_scratchpad armazena o status da validação. Isso impede que o return seja acionado antes do GlideAjax retornar com a informação
    if (g_scratchpad.isFormValid) {
        return true;
    }

    //pegando o botão de submit do formulário
    var actionName = g_form.getActionName();

    var schedule = g_form.getValue('training_schedule');

    var ga = new GlideAjax('EnrollmentValidation');
    ga.addParam('sysparm_name', 'validateEnrollment');
    ga.addParam('sysparm_schedule', schedule);

    ga.getXMLAnswer(function(answer) {
        switch (answer) {
            case 'already_enrolled':
                g_form.addErrorMessage('You are already enrolled in this training schedule.');
                g_scratchpad.isFormValid = false;
                break;
            case 'limit_reached':
                g_form.addErrorMessage('You have reached the maxium of 3 enrollment for this course.');
                break;
            case 'no_seats_available':
                g_form.addErrorMessage('This training is already full.');
                break;
            case 'instructor_cannot_enroll':
                g_form.addErrorMessage('You cannot enroll in a training you are intructing.');
                break;
            case 'too_late':
                g_form.addErrorMessage('You can only enroll up to one day before the training date.');
                break;
            case 'schedule_not_found':
                g_form.addErrorMessage('Training schedule not found.');
                break;
            case 'ok':
                g_scratchpad.isFormValid = true;
                g_form.submit(actionName);
                return;
        }
    });

    return false;
}
